    int minSourceFragSize = source.stream()
                                  .mapToInt(s -> s.getMinConcordantFragmentSize())
                                  .min() // Use min instead of max to get the smallest size
                                  .orElse(Integer.MAX_VALUE); // Default to maximum possible int value if no sources

    // Step 2: If file exists, ensure to check if the super class's max size affects the minimum
    if (getFile().exists()) {
        // Correct logic should ensure we are correctly comparing sizes to find the true minimum
        minSourceFragSize = Math.min(super.getMaxConcordantFragmentSize(), minSourceFragSize);
    }

    return minSourceFragSize;
}

